#!/usr/bin/env python3
from pathlib import Path
import py_compile
import shutil

path = Path("memex/process_queue_once.py")
if not path.exists(): raise SystemExit("ERROR: run from /data/projects/hedgedoc")
text = path.read_text(encoding="utf-8")
original = text
if "MEMEX_LLM_ASSOCIATION_SYNC" in text: raise SystemExit("ERROR: LLM associated_with patch already appears to be applied")

def replace_once(old, new, label):
    global text
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"ERROR: {label}: expected 1 match, found {count}; file not modified")
    text = text.replace(old, new, 1)

replace_once('MODEL = "gemma4:26b"\n', 'MODEL = "gemma4:26b"\n\n# MEMEX_LLM_ASSOCIATION_SYNC\nASSOCIATIONS_FILE = Path(\n    os.environ.get(\n        "MEMEX_ASSOCIATIONS_FILE",\n        "/data/projects/hedgedoc-nb-frontend/data/memex-associations.json",\n    )\n)\nASSOCIATION_MIN_CONFIDENCE = float(\n    os.environ.get("MEMEX_LLM_ASSOCIATION_MIN_CONFIDENCE", "0.85")\n)\n', 'association store configuration')
replace_once('# Previously processed sources are represented by memex/index.md summaries.', '\ndef parse_json_object(text):\n    if not isinstance(text, str):\n        raise ValueError("Ollama response content is not text")\n\n    start = text.find("{")\n    if start < 0:\n        raise ValueError("Ollama response contained no JSON object")\n\n    value, _ = json.JSONDecoder().raw_decode(text[start:])\n    if not isinstance(value, dict):\n        raise ValueError("Ollama response JSON must be an object")\n    return value\n\n\ndef verify_direct_association(source_doc, source_content, target_doc, target_content):\n    prompt = f"""\nYou are verifying one proposed direct Memex source-to-source association.\n\nA direct association means a user could meaningfully move from SOURCE A to\nSOURCE B because the documents themselves contain a concrete substantive\nrelationship.\n\nAccept examples include:\n- both documents concern the same identifiable building, place, person,\n  object, event, project, or work and provide complementary evidence;\n- one document directly describes, conserves, records, explains, or provides\n  provenance for the subject documented by the other;\n- a specific causal, historical, ownership, part-whole, or documentary\n  relationship is supported by the text.\n\nReject an association when the only basis is:\n- membership in the same Memex trail;\n- a broad shared topic or category;\n- title or keyword similarity;\n- geographic proximity by itself;\n- chronology by itself;\n- a speculative relationship not supported by the supplied documents.\n\nReturn JSON only:\n{{\n  "associated": true,\n  "reason": "one concise evidence-based reason",\n  "confidence": 0.0\n}}\n\nUse false when the evidence is not strong enough. Zero associations is valid.\n\nSOURCE A\nalias: {source_doc[\'alias\']}\ntitle: {source_doc[\'title\']}\n\n{source_content}\n\nSOURCE B\nalias: {target_doc[\'alias\']}\ntitle: {target_doc[\'title\']}\n\n{target_content}\n"""\n\n    payload = json.dumps({\n        "model": MODEL,\n        "messages": [{"role": "user", "content": prompt}],\n        "stream": False,\n        "format": "json",\n        "options": {\n            "temperature": 0.1,\n            "num_ctx": 32768,\n        },\n    }).encode()\n\n    request = urllib.request.Request(\n        OLLAMA,\n        data=payload,\n        headers={"Content-Type": "application/json"},\n    )\n\n    with urllib.request.urlopen(request, timeout=600) as response:\n        outer = json.loads(response.read().decode())\n\n    return parse_json_object(\n        outer.get("message", {}).get("content", "")\n    )\n\n\ndef sync_llm_associations(source_alias, proposals):\n    if not ASSOCIATIONS_FILE.exists():\n        raise RuntimeError(\n            f"Canonical Memex association store not found: {ASSOCIATIONS_FILE}"\n        )\n\n    store = json.loads(ASSOCIATIONS_FILE.read_text(encoding="utf-8"))\n    if not isinstance(store, dict) or not isinstance(store.get("associations"), list):\n        raise RuntimeError(\n            f"Invalid canonical Memex association store: {ASSOCIATIONS_FILE}"\n        )\n\n    existing = store["associations"]\n\n    def pair_key(source, target):\n        return tuple(sorted((str(source).strip(), str(target).strip())))\n\n    kept = []\n    removed = 0\n\n    for item in existing:\n        if (\n            isinstance(item, dict)\n            and item.get("relation") == "associated_with"\n            and item.get("createdBy") == "llm"\n            and source_alias in {\n                str(item.get("source", "")).strip(),\n                str(item.get("target", "")).strip(),\n            }\n        ):\n            removed += 1\n            continue\n\n        kept.append(item)\n\n    occupied_pairs = {\n        pair_key(item.get("source", ""), item.get("target", ""))\n        for item in kept\n        if isinstance(item, dict)\n        and str(item.get("source", "")).strip()\n        and str(item.get("target", "")).strip()\n    }\n\n    added = 0\n\n    for proposal in proposals:\n        target_alias = str(proposal["target"]).strip()\n        if not target_alias or target_alias == source_alias:\n            continue\n\n        source, target = sorted((source_alias, target_alias))\n        key = pair_key(source, target)\n\n        # A user-created edge for the same pair wins.\n        if key in occupied_pairs:\n            continue\n\n        kept.append({\n            "source": source,\n            "target": target,\n            "relation": "associated_with",\n            "createdBy": "llm",\n            "reason": proposal["reason"],\n        })\n        occupied_pairs.add(key)\n        added += 1\n\n    kept.sort(\n        key=lambda item: (\n            str(item.get("source", "")) if isinstance(item, dict) else "",\n            str(item.get("target", "")) if isinstance(item, dict) else "",\n            str(item.get("createdBy", "")) if isinstance(item, dict) else "",\n        )\n    )\n\n    output = {\n        "version": 2,\n        "associations": kept,\n    }\n\n    tmp = ASSOCIATIONS_FILE.with_name(\n        f"{ASSOCIATIONS_FILE.name}.tmp-{os.getpid()}"\n    )\n    tmp.write_text(\n        json.dumps(output, indent=2) + "\\n",\n        encoding="utf-8",\n    )\n    os.replace(tmp, ASSOCIATIONS_FILE)\n\n    return {\n        "removed": removed,\n        "added": added,\n        "total": len(kept),\n    }\n\n\n# Previously processed sources are represented by memex/index.md summaries.', 'association helper insertion')
replace_once('Do not rewrite summaries merely because a document is INDEX SUMMARY ONLY.', 'Do not rewrite summaries merely because a document is INDEX SUMMARY ONLY.\n\nThe top-level JSON field "associations" is REQUIRED, even when it is empty.\nIt contains candidate direct relationships from the NEW OR REVISED source only:\n\n"associations": [\n  {{\n    "target": 2,\n    "reason": "why the new/revised source may be directly associated with DOCUMENT 2"\n  }}\n]\n\nAssociation candidate rules:\n- The source is implicitly DOCUMENT {queued_doc[\'id\']}; return only target IDs.\n- A target must be another supplied DOCUMENT.\n- Zero candidates is valid: return "associations": [].\n- Do not create a candidate merely because two documents share a trail,\n  broad topic, place category, chronology, title words, or keywords.\n- Propose a candidate only when the maintained summary gives a concrete reason\n  to inspect the two full source documents for a direct relationship.\n- These are candidates only. The processor will fetch the target\'s full\n  HedgeDoc content and independently verify the relationship before writing\n  canonical associated_with data.', 'prompt association contract')
replace_once('content = response.get("message", {}).get("content", "")\nstart = content.find("{")\nif start < 0:\n    raise ValueError("Ollama response contained no JSON object")\nresult, _ = json.JSONDecoder().raw_decode(content[start:])', 'ollama_content = response.get("message", {}).get("content", "")\nresult = parse_json_object(ollama_content)', 'main Ollama parser')
replace_once('id_to_doc = {d["id"]: d for d in docs}', 'id_to_doc = {d["id"]: d for d in docs}\n\nraw_association_candidates = result.get("associations")\nif not isinstance(raw_association_candidates, list):\n    raise ValueError(\n        \'Ollama response must contain top-level "associations" array\'\n    )\n\ncandidate_targets = []\nseen_target_ids = set()\n\nfor item in raw_association_candidates:\n    if not isinstance(item, dict):\n        continue\n\n    try:\n        target_id = int(item.get("target"))\n    except (TypeError, ValueError):\n        continue\n\n    if (\n        target_id == queued_doc["id"]\n        or target_id not in id_to_doc\n        or target_id in seen_target_ids\n    ):\n        continue\n\n    seen_target_ids.add(target_id)\n    candidate_targets.append(target_id)\n\nverified_llm_associations = []\n\nfor target_id in candidate_targets:\n    target_doc = id_to_doc[target_id]\n    target_content = api_get(f"{target_doc[\'alias\']}/content")\n\n    print(\n        "Verifying associated_with:",\n        queued_alias,\n        "<->",\n        target_doc["alias"],\n    )\n\n    verification = verify_direct_association(\n        queued_doc,\n        content,\n        target_doc,\n        target_content,\n    )\n\n    associated = verification.get("associated") is True\n    reason = " ".join(str(verification.get("reason", "")).split())\n\n    try:\n        confidence = float(verification.get("confidence", 0))\n    except (TypeError, ValueError):\n        confidence = 0.0\n\n    if (\n        associated\n        and reason\n        and confidence >= ASSOCIATION_MIN_CONFIDENCE\n    ):\n        verified_llm_associations.append({\n            "target": target_doc["alias"],\n            "reason": reason,\n            "confidence": confidence,\n        })\n\nprint(\n    "LLM association verification:",\n    f"candidates={len(candidate_targets)}",\n    f"accepted={len(verified_llm_associations)}",\n    f"min-confidence={ASSOCIATION_MIN_CONFIDENCE:.2f}",\n)', 'association candidate verification')
replace_once('"Canonical Memex association and trail files were not modified.",', '"Canonical direct associations are synchronized only after successful lint; trail membership remains separate.",', 'generated note association status')
replace_once('# Mark queue entry processed', '# Synchronize verified direct associations only after the candidate\n# index/nodeBook state has passed lint. A failure restores the generated\n# outputs and leaves this queue item pending.\ntry:\n    association_sync = sync_llm_associations(\n        queued_alias,\n        verified_llm_associations,\n    )\nexcept Exception as exc:\n    print(\n        "Association sync failed; restoring previous index and nodeBook...",\n        file=__import__("sys").stderr,\n    )\n    INDEX_PATH.write_text(old_index, encoding="utf-8")\n    api_put(NODEBOOK, old_nodebook)\n    raise SystemExit(\n        f"Memex association sync rejected {queued_alias}: {exc}; "\n        "previous index/nodeBook restored; queue item remains pending"\n    )\n\n# Mark queue entry processed', 'post-lint association sync')
replace_once('print("Canonical Memex files were NOT modified.")', 'print(\n    "LLM associations:",\n    f"added={association_sync[\'added\']}",\n    f"replaced={association_sync[\'removed\']}",\n    f"total={association_sync[\'total\']}",\n)\nprint("association store:", ASSOCIATIONS_FILE)', 'runtime association summary')
replace_once('f"- trails: {len(trails)}\\n"', 'f"- trails: {len(trails)}\\n"\n            f"- LLM associated_with accepted: {len(verified_llm_associations)}\\n"', 'Memex log association count')

backup = Path("/tmp/process_queue_once.py.before-llm-associated-with")
shutil.copy2(path, backup)
path.write_text(text, encoding="utf-8")
try:
    py_compile.compile(str(path), doraise=True)
except Exception:
    path.write_text(original, encoding="utf-8")
    raise SystemExit("ERROR: syntax check failed; original source restored")
print("PATCHED: memex/process_queue_once.py")
print("SYNTAX OK")
print("BACKUP:", backup)
print("ASSOCIATION STORE: /data/projects/hedgedoc-nb-frontend/data/memex-associations.json")
print("MODE: full-content verification -> createdBy=llm")
